def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, sorted(a)))
    tests = [fmt([0]), fmt([-5]), fmt([7]), fmt([-1, 1]), fmt([0, 0, 0]), fmt([-3, -2, -1]), fmt([1, 2, 3]), fmt([-2, -2, 2, 2])]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(2):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(30)]))
    tests.append(fmt([rng.randint(-10**9, 0) for _ in range(30)]))
    N = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(-1000, 1000) for _ in range(N)]))
    tests.append(fmt([-(10**9) + i for i in range(N)]))
    tests.append(fmt([x for k in range(N // 2) for x in (-k, k)]))
    return tests

